import React, { useEffect, useMemo, useRef, useState } from 'react';
import Swal from 'sweetalert2';
import { faArrowDown, faArrowUp, faPen, faPlus, faTrash } from '@fortawesome/free-solid-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import axios from '../axios';
import { ORDEN_SECCIONES, SECCIONES } from '../utils/expedienteChecklist';
import { avisarError } from '../utils/avisosPlantillas';
import { opcionesEtapa } from '../utils/contratacion';
import {
    CARACTERES, CATEGORIAS, CONDICIONADO, FUENTES_NORMATIVAS, PESO_MAXIMO, PESO_MINIMO, SIN_ETAPA, TIPOS_REQUISITO, USO_CONTRATACION, agruparPorEtapa,
    datosRequisito, erroresDelRequisito, etiquetaCaracter, etiquetaCategoria, etiquetaPeso, formularioRequisito, htmlErrores, mensajeApi, mover,
    opcionesResponsable, ordenTrasMoverEnEtapa, porRedactar, requisitoVacio, sinEtapa, usoDePlantilla,
} from '../utils/plantillasChecklist';
import useOcupado from './useOcupado';
import '../../css/Contratacion.css';

const Campo = ({ etiqueta, children, ancho }) => (
    <label className={`pl-campo${ancho ? ' pl-campo-ancho' : ''}`}>
        <span>{etiqueta}</span>
        {children}
    </label>
);

/**
 * Formulario de un requisito. En el motor sgr agrega sección, sector, tipo y condición.
 * `responsables` es el catálogo de Responsables (para elegir personas), o null si no se pudo cargar.
 * En una plantilla de contratación pide la etapa: `etapas` es su catálogo (null mientras carga o si
 * falló, con `avisoEtapas`) y `errorEtapa`, { texto, enfocar } con lo que el servidor objetó de
 * ella y si el foco debe ir ya al campo (no mientras se muestra el aviso con los demás errores).
 * También pide el peso del requisito en el avance; `errorPeso` es como `errorEtapa`, para el peso.
 */
const FormularioRequisito = ({
    motor, esSgr, contratacion, inicial, catalogoSgr, responsables, etapas, avisoEtapas, errorEtapa, onCambioEtapa, errorPeso, onCambioPeso,
    guardando, onGuardar, onCancelar,
}) => {
    const [f, setF] = useState(inicial);
    const [revisionCondicion, setRevisionCondicion] = useState(null);
    const campoEtapa = useRef(null);
    const campoPeso = useRef(null);
    const cambiar = (campo, valor) => setF((actual) => ({ ...actual, [campo]: valor }));

    // Si el servidor objeta la etapa o el peso, el foco va al campo, donde se muestra el error.
    useEffect(() => {
        if (errorEtapa?.enfocar) campoEtapa.current?.focus();
    }, [errorEtapa]);
    useEffect(() => {
        if (errorPeso?.enfocar) campoPeso.current?.focus();
    }, [errorPeso]);

    const texto = (campo, props = {}) => <input value={f[campo]} onChange={(e) => cambiar(campo, e.target.value)} {...props} />;
    // Las personas salen de los responsables activos; la que el requisito ya tiene se conserva
    // aunque esté inactiva, y un cargo sin persona (dato anterior), como "Solo cargo". Sin el
    // catálogo se escribe el cargo a mano, como antes, y la persona no cambia.
    const persona = (campoId, campoCargo, campoPersona) => {
        if (responsables === null) {
            return (
                <>
                    {texto(campoCargo, { maxLength: 150 })}
                    {f[campoPersona] && <small className="pl-ayuda">Asignado a {f[campoPersona].nombre}. Sin la lista de responsables, por ahora solo puedes cambiar el cargo.</small>}
                </>
            );
        }
        const actual = { persona: f[campoPersona], cargo: f[campoPersona] ? null : f[campoCargo] };
        return (
            <select value={f[campoId]} onChange={(e) => cambiar(campoId, e.target.value)}>
                {opcionesResponsable(responsables, actual).map((o) => <option key={o.valor} value={o.valor}>{o.etiqueta}</option>)}
            </select>
        );
    };
    const sinPersonas = responsables !== null && !responsables.some((r) => r.activo);
    const sufijo = responsables === null ? ' (cargo)' : '';

    const sector = catalogoSgr?.sectores.find((s) => s.id === Number(f.sector_id));

    const validarCondicion = async () => {
        try {
            const { data } = await axios.post('/catalogo-requisitos/validar-condicion', { condicion: f.condicion });
            setRevisionCondicion(data.valida ? 'La condición es válida.' : data.errores.join(' '));
        } catch (e) {
            setRevisionCondicion(mensajeApi(e));
        }
    };

    return (
        <form className="gp-panel pl-formulario pl-formulario-requisito" onSubmit={(e) => { e.preventDefault(); onGuardar(f); }}>
            <Campo etiqueta="Nombre del requisito" ancho>
                <textarea rows={2} required autoFocus value={f.texto} onChange={(e) => cambiar('texto', e.target.value)} />
            </Campo>
            <Campo etiqueta="Descripción" ancho>
                <textarea rows={2} value={f.descripcion} onChange={(e) => cambiar('descripcion', e.target.value)} />
            </Campo>

            {/* El error y el aviso quedan fuera del <label>: se leen como descripción, no como nombre del campo. */}
            {contratacion && (
                <div className="pl-campo">
                    <label htmlFor="pl-etapa">Etapa</label>
                    <select
                        id="pl-etapa"
                        ref={campoEtapa}
                        required
                        value={f.etapa_id}
                        aria-invalid={Boolean(errorEtapa)}
                        aria-describedby={[errorEtapa && 'pl-etapa-error', avisoEtapas && 'pl-etapa-aviso'].filter(Boolean).join(' ') || undefined}
                        onChange={(e) => { cambiar('etapa_id', e.target.value); onCambioEtapa(); }}
                    >
                        <option value="">Elige la etapa</option>
                        {opcionesEtapa(etapas, f.etapa_actual).map((o) => <option key={o.valor} value={o.valor}>{o.etiqueta}</option>)}
                    </select>
                    {errorEtapa && <small id="pl-etapa-error" className="ct-error-campo">{errorEtapa.texto}</small>}
                    {avisoEtapas && <small id="pl-etapa-aviso" className="pl-ayuda">{avisoEtapas}</small>}
                </div>
            )}
            {contratacion && (
                <div className="pl-campo">
                    <label htmlFor="pl-peso">Peso</label>
                    <input
                        id="pl-peso"
                        ref={campoPeso}
                        type="number"
                        inputMode="numeric"
                        required
                        min={PESO_MINIMO}
                        max={PESO_MAXIMO}
                        step={1}
                        value={f.peso}
                        aria-invalid={Boolean(errorPeso)}
                        aria-describedby={[errorPeso && 'pl-peso-error', 'pl-peso-ayuda'].filter(Boolean).join(' ')}
                        onChange={(e) => { cambiar('peso', e.target.value); onCambioPeso(); }}
                    />
                    {errorPeso && <small id="pl-peso-error" className="ct-error-campo">{errorPeso.texto}</small>}
                    <small id="pl-peso-ayuda" className="pl-ayuda">Cuánto pesa en el avance del proceso. 1 si todos valen lo mismo.</small>
                </div>
            )}

            {motor === 'sgr' && (
                <>
                    <Campo etiqueta="Clave">{texto('clave', { required: true, maxLength: 40, pattern: '[a-z0-9_]+', title: 'Solo minúsculas, números y guion bajo.' })}</Campo>
                    <Campo etiqueta="Código">{texto('codigo', { required: true, maxLength: 60 })}</Campo>
                    <Campo etiqueta="Sección">
                        <select value={f.seccion} onChange={(e) => cambiar('seccion', e.target.value)}>
                            {ORDEN_SECCIONES.map((s) => <option key={s} value={s}>{SECCIONES[s].num} {SECCIONES[s].titulo}</option>)}
                        </select>
                    </Campo>
                    <Campo etiqueta="Fuente normativa">
                        <select value={f.fuente} onChange={(e) => cambiar('fuente', e.target.value)}>
                            {FUENTES_NORMATIVAS.map(([v, t]) => <option key={v} value={v}>{t}</option>)}
                        </select>
                    </Campo>
                    {f.seccion === 'C' && (
                        <>
                            <Campo etiqueta="Sector SGR">
                                <select value={f.sector_id} onChange={(e) => setF((a) => ({ ...a, sector_id: e.target.value, tipo_id: '' }))}>
                                    <option value="">Elige un sector</option>
                                    {(catalogoSgr?.sectores ?? []).map((s) => <option key={s.id} value={s.id}>{s.nombre}{!s.activo && ' (inactivo)'}</option>)}
                                </select>
                            </Campo>
                            <Campo etiqueta="Tipo de proyecto">
                                <select value={f.tipo_id} onChange={(e) => cambiar('tipo_id', e.target.value)}>
                                    <option value="">Todo el sector</option>
                                    {(sector?.tipos ?? []).map((t) => <option key={t.id} value={t.id}>{t.nombre}{!t.activo && ' (inactivo)'}</option>)}
                                </select>
                            </Campo>
                        </>
                    )}
                    <Campo etiqueta="Subtítulo">{texto('subtitulo', { maxLength: 255 })}</Campo>
                    <div className="pl-campo">
                        <span id="pl-condicion-etiqueta">Condición (evaluador SGR)</span>
                        <span className="pl-en-linea">
                            <input
                                aria-labelledby="pl-condicion-etiqueta"
                                value={f.condicion}
                                maxLength={255}
                                placeholder="siempre, fase=3, comp=predios…"
                                onChange={(e) => { cambiar('condicion', e.target.value); setRevisionCondicion(null); }}
                            />
                            <button type="button" className="gp-boton" onClick={validarCondicion}>Validar</button>
                        </span>
                        {revisionCondicion && <small className="pl-ayuda" role="status">{revisionCondicion}</small>}
                    </div>
                </>
            )}

            <Campo etiqueta="Categoría">
                <select value={f.categoria} onChange={(e) => cambiar('categoria', e.target.value)}>
                    <option value="">Sin categoría</option>
                    {CATEGORIAS.map(([v, t]) => <option key={v} value={v}>{t}</option>)}
                </select>
            </Campo>
            <Campo etiqueta="Tipo de requisito">
                <select value={f.tipo_requisito} onChange={(e) => cambiar('tipo_requisito', e.target.value)}>
                    <option value="">Sin definir</option>
                    {TIPOS_REQUISITO.map(([v, t]) => <option key={v} value={v}>{t}</option>)}
                </select>
            </Campo>

            {motor === 'simple' && (
                <>
                    <Campo etiqueta="Carácter">
                        <select value={f.caracter} onChange={(e) => cambiar('caracter', e.target.value)}>
                            {CARACTERES.map(([v, t]) => <option key={v} value={v}>{t}</option>)}
                        </select>
                    </Campo>
                    {f.caracter === CONDICIONADO && (
                        <Campo etiqueta="¿Cuándo aplica?" ancho>
                            <textarea rows={2} required value={f.condicion_descripcion} onChange={(e) => cambiar('condicion_descripcion', e.target.value)} />
                            {porRedactar(f) && (
                                <small className="pl-ayuda">Reemplaza la "Condición original" por una descripción en palabras de cuándo aplica este requisito.</small>
                            )}
                        </Campo>
                    )}
                </>
            )}

            <Campo etiqueta={`Responsable de cumplimiento${sufijo}`}>{persona('responsable_cumplimiento_id', 'cargo_cumplimiento', 'persona_cumplimiento')}</Campo>
            <Campo etiqueta={`Responsable de revisión${sufijo}`}>{persona('responsable_revision_id', 'cargo_revision', 'persona_revision')}</Campo>
            {sinPersonas && (
                <p className="pl-ayuda pl-campo-ancho">No hay responsables activos. Regístralos en Parámetros → Responsables.</p>
            )}
            <Campo etiqueta="Documento o soporte requerido">{texto('soporte_requerido', { maxLength: 255 })}</Campo>
            <Campo etiqueta="Referencia normativa">{texto('referencia_normativa', { maxLength: 255 })}</Campo>
            {!esSgr && <Campo etiqueta="Código común (para no repetir entre plantillas)">{texto('codigo_comun', { maxLength: 40 })}</Campo>}
            <Campo etiqueta="Observaciones e instrucciones" ancho>
                <textarea rows={2} value={f.nota} onChange={(e) => cambiar('nota', e.target.value)} />
            </Campo>
            <label className="pl-check">
                <input type="checkbox" checked={f.activo} onChange={(e) => cambiar('activo', e.target.checked)} /> Activo
            </label>
            {esSgr ? (
                <p className="pl-ayuda">En la plantilla SGR todo "no aplica" necesita aprobación.</p>
            ) : (
                <label className="pl-check">
                    <input type="checkbox" checked={f.requiere_aprobacion_no_aplica} onChange={(e) => cambiar('requiere_aprobacion_no_aplica', e.target.checked)} />
                    El "no aplica" necesita aprobación
                </label>
            )}

            <div className="pl-formulario-acciones">
                <button type="button" className="gp-boton" onClick={onCancelar} disabled={guardando}>Cancelar</button>
                <button type="submit" className="gp-boton gp-boton-primario" disabled={guardando}>Guardar requisito</button>
            </div>
        </form>
    );
};

/** Una fila de la lista de requisitos, con sus acciones si la versión es un borrador. */
const FilaRequisito = ({ requisito: r, motor, contratacion, editable, ocupado, primero, ultimo, onMover, onEditar, onEliminar }) => (
    <li className={r.activo ? '' : 'inactivo'}>
        <div className="pl-fila-texto">
            <span className="pl-codigo">{r.codigo || r.clave}</span>
            <span>{r.texto}</span>
            <span className="pl-fila-etiquetas">
                {r.categoria && <span className="pl-insignia pl-insignia-suave">{etiquetaCategoria(r.categoria)}</span>}
                {motor === 'simple' && <span className="pl-insignia pl-insignia-suave">{etiquetaCaracter(r.caracter)}</span>}
                {contratacion && etiquetaPeso(r.peso) && <span className="pl-insignia pl-insignia-suave">{etiquetaPeso(r.peso)}</span>}
                {porRedactar(r) && <span className="pl-insignia pl-insignia-alerta">Por redactar</span>}
                {!r.activo && <span className="pl-insignia pl-insignia-alerta">Inactivo</span>}
            </span>
        </div>
        {editable && (
            <div className="pl-fila-acciones">
                <button type="button" className="gp-icono" aria-label={`Subir ${r.texto}`} disabled={ocupado || primero} onClick={() => onMover(-1)}>
                    <FontAwesomeIcon icon={faArrowUp} />
                </button>
                <button type="button" className="gp-icono" aria-label={`Bajar ${r.texto}`} disabled={ocupado || ultimo} onClick={() => onMover(1)}>
                    <FontAwesomeIcon icon={faArrowDown} />
                </button>
                <button type="button" className="gp-icono" aria-label={`Editar ${r.texto}`} disabled={ocupado} data-foco={`editar-${r.id}`} onClick={onEditar}>
                    <FontAwesomeIcon icon={faPen} />
                </button>
                <button type="button" className="gp-icono" aria-label={`Eliminar ${r.texto}`} disabled={ocupado} onClick={onEliminar}>
                    <FontAwesomeIcon icon={faTrash} />
                </button>
            </div>
        )}
    </li>
);

/**
 * Requisitos de la versión de trabajo: se editan en borrador; una versión publicada solo se lee.
 * En una plantilla de contratación cada requisito lleva su etapa y la lista se agrupa por etapa,
 * en el orden del catálogo; las flechas mueven un requisito entre los de su etapa.
 */
const PlantillaRequisitos = ({ plantilla, version, requisitos, onCambio }) => {
    const [editando, setEditando] = useState(null); // null, 'nuevo' o el requisito
    const [catalogoSgr, setCatalogoSgr] = useState(null);
    // Responsables, para elegir las personas del requisito. null mientras carga o si falla.
    const [responsables, setResponsables] = useState(null);
    // Etapas de contratación, para el select del requisito. null mientras cargan o si fallan.
    const [etapas, setEtapas] = useState(null);
    const [avisoEtapas, setAvisoEtapas] = useState(null);
    const [errorEtapa, setErrorEtapa] = useState(null); // { texto, enfocar } del servidor, bajo el campo
    const [errorPeso, setErrorPeso] = useState(null); // lo mismo, para el peso
    const [ocupado, ejecutar] = useOcupado();
    const contenedor = useRef(null);
    const retorno = useRef(null); // data-foco del botón que abrió el formulario
    const editable = version?.estado === 'borrador';
    const esSgr = plantilla.es_sgr;
    const uso = usoDePlantilla(plantilla);
    const contratacion = uso === USO_CONTRATACION;
    const url = version ? `/catalogo-requisitos/versiones/${version.id}` : null;
    const grupos = useMemo(() => (contratacion ? agruparPorEtapa(requisitos, etapas) : null), [contratacion, requisitos, etapas]);

    useEffect(() => {
        if (plantilla.motor !== 'sgr') return undefined;
        let vigente = true;
        axios.get('/catalogo-requisitos/vigente', { params: { incluir_inactivos: 1 } })
            .then(({ data }) => { if (vigente) setCatalogoSgr(data); })
            .catch((e) => { if (vigente) avisarError('No se pudo cargar el catálogo SGR (sectores y tipos)', e); });
        return () => { vigente = false; };
    }, [plantilla.motor]);

    useEffect(() => {
        if (!contratacion) return undefined;
        let vigente = true;
        axios.get('/etapasContratacion')
            .then(({ data }) => { if (vigente) setEtapas(Array.isArray(data) ? data : null); })
            .catch((e) => { if (vigente) setAvisoEtapas(`No se pudo cargar la lista de etapas. ${mensajeApi(e)}`); });
        return () => { vigente = false; };
    }, [contratacion]);

    // Si falla, el formulario deja escribir los cargos a mano: no hace falta avisar.
    useEffect(() => {
        let vigente = true;
        axios.get('/responsables')
            .then(({ data }) => { if (vigente) setResponsables(Array.isArray(data) ? data : null); })
            .catch(() => { if (vigente) setResponsables(null); });
        return () => { vigente = false; };
    }, []);

    // Al cerrar el formulario, el foco vuelve al botón que lo abrió.
    useEffect(() => {
        if (editando || !retorno.current) return;
        contenedor.current?.querySelector(`[data-foco="${retorno.current}"]`)?.focus();
        retorno.current = null;
    }, [editando]);

    const abrir = (requisito) => {
        retorno.current = requisito === 'nuevo' ? 'nuevo' : `editar-${requisito.id}`;
        setErrorEtapa(null);
        setErrorPeso(null);
        setEditando(requisito);
    };

    const cerrar = () => {
        setErrorEtapa(null);
        setErrorPeso(null);
        setEditando(null);
    };

    const crearBorrador = () => ejecutar(async () => {
        try {
            await axios.post(`/plantillas/${plantilla.id}/versiones`, { descripcion: null });
            await onCambio();
        } catch (e) {
            avisarError('No se pudo crear el borrador', e);
        }
    });

    const guardar = (formulario) => ejecutar(async () => {
        const datos = datosRequisito(formulario, plantilla.motor, responsables !== null, uso);
        try {
            if (editando === 'nuevo') {
                await axios.post(`${url}/requisitos`, datos);
            } else {
                await axios.put(`${url}/requisitos/${editando.id}`, datos);
            }
            cerrar();
            await onCambio();
        } catch (e) {
            // Lo que el servidor objeta de la etapa y del peso va bajo su campo; el resto, en el aviso
            // de siempre. El foco termina en el primero con error (la etapa y, si no, el peso):
            // enseguida si no hay aviso o, si lo hay, al cerrarlo (el aviso no lo devuelve a
            // "Guardar requisito").
            const repartidos = contratacion ? erroresDelRequisito(e) : null;
            if (!repartidos?.etapa.length && !repartidos?.peso.length) {
                avisarError('No se pudo guardar el requisito', e);
                return;
            }
            const deEtapa = repartidos.etapa.length ? repartidos.etapa.join(' ') : null;
            const dePeso = repartidos.peso.length ? repartidos.peso.join(' ') : null;
            const marcar = (enfocar) => {
                setErrorEtapa(deEtapa ? { texto: deEtapa, enfocar } : null);
                setErrorPeso(dePeso ? { texto: dePeso, enfocar: enfocar && !deEtapa } : null);
            };
            if (!repartidos.otros.length) {
                marcar(true);
                return;
            }
            marcar(false);
            await Swal.fire({
                icon: 'error',
                titleText: 'No se pudo guardar el requisito',
                html: htmlErrores(repartidos.mensaje, repartidos.otros),
                returnFocus: false,
            });
            if (deEtapa) setErrorEtapa((actual) => (actual ? { ...actual, enfocar: true } : actual));
            else setErrorPeso((actual) => (actual ? { ...actual, enfocar: true } : actual));
        }
    });

    const eliminar = (requisito) => ejecutar(async () => {
        const { isConfirmed } = await Swal.fire({
            icon: 'warning',
            titleText: '¿Eliminar este requisito del borrador?',
            text: requisito.texto,
            showCancelButton: true,
            confirmButtonText: 'Sí, eliminar',
            cancelButtonText: 'Cancelar',
        });
        if (!isConfirmed) return;
        try {
            await axios.delete(`${url}/requisitos/${requisito.id}`);
            await onCambio();
        } catch (e) {
            avisarError('No se pudo eliminar el requisito', e);
        }
    });

    // Los botones quedan deshabilitados hasta que llega la recarga con el orden nuevo. Se envía el
    // orden de toda la versión; en contratación, el que se ve (por etapas), con el requisito
    // cambiado por el vecino de su etapa, para que el orden guardado coincida con la lista.
    const moverRequisito = (requisito, delta) => ejecutar(async () => {
        const nueva = contratacion
            ? ordenTrasMoverEnEtapa(requisitos, requisito.id, delta, etapas)
            : mover(requisitos, requisitos.indexOf(requisito), delta);
        if (!nueva) return;
        const ids = nueva.map((r) => r.id);
        try {
            await axios.put(`${url}/requisitos-orden`, { ids });
            await onCambio();
        } catch (e) {
            avisarError('No se pudo cambiar el orden', e);
        }
    });

    const porRedactarTotal = requisitos.filter((r) => r.activo && porRedactar(r)).length;
    // Publicar exige la etapa de cada requisito activo; los inactivos sin etapa no lo impiden.
    const sinEtapaActivos = contratacion ? requisitos.filter((r) => r.activo && sinEtapa(r)).length : 0;

    if (!version) {
        return (
            <div className="gp-panel pl-aviso">
                <p>La plantilla no tiene versiones.</p>
                <button type="button" className="gp-boton gp-boton-primario" onClick={crearBorrador} disabled={ocupado}>Crear borrador</button>
            </div>
        );
    }

    if (editando) {
        return (
            <FormularioRequisito
                motor={plantilla.motor}
                esSgr={esSgr}
                contratacion={contratacion}
                catalogoSgr={catalogoSgr}
                responsables={responsables}
                etapas={etapas}
                avisoEtapas={avisoEtapas}
                errorEtapa={errorEtapa}
                onCambioEtapa={() => setErrorEtapa(null)}
                errorPeso={errorPeso}
                onCambioPeso={() => setErrorPeso(null)}
                guardando={ocupado}
                inicial={editando === 'nuevo' ? requisitoVacio(plantilla.motor, uso) : formularioRequisito(editando, plantilla.motor, uso)}
                onGuardar={guardar}
                onCancelar={cerrar}
            />
        );
    }

    const fila = (r, primero, ultimo) => (
        <FilaRequisito
            key={r.id}
            requisito={r}
            motor={plantilla.motor}
            contratacion={contratacion}
            editable={editable}
            ocupado={ocupado}
            primero={primero}
            ultimo={ultimo}
            onMover={(delta) => moverRequisito(r, delta)}
            onEditar={() => abrir(r)}
            onEliminar={() => eliminar(r)}
        />
    );

    return (
        <div className="pl-requisitos" ref={contenedor}>
            <div className="pl-barra">
                <p className="pl-ayuda">
                    {editable
                        ? `Editando el borrador v${version.numero}. Los cambios se ven en los expedientes nuevos cuando se publique.`
                        : `La versión v${version.numero} está publicada y no se modifica.`}
                </p>
                {editable ? (
                    <button type="button" className="gp-boton gp-boton-primario" data-foco="nuevo" onClick={() => abrir('nuevo')}>
                        <FontAwesomeIcon icon={faPlus} /> Agregar requisito
                    </button>
                ) : (
                    <button type="button" className="gp-boton gp-boton-primario" onClick={crearBorrador} disabled={ocupado}>Crear borrador para editar</button>
                )}
            </div>

            {porRedactarTotal > 0 && (
                <p className="pl-aviso-suave" role="status">
                    {porRedactarTotal} {porRedactarTotal === 1 ? 'condicionado por redactar' : 'condicionados por redactar'}: describe en palabras cuándo aplica cada uno antes de publicar.
                </p>
            )}

            {requisitos.length === 0 && <p className="gp-vacio">Esta versión aún no tiene requisitos.</p>}

            {grupos ? grupos.map((g) => (
                <section key={g.clave} className="pl-grupo" aria-labelledby={`pl-grupo-${g.clave}`}>
                    <h2 id={`pl-grupo-${g.clave}`} className="pl-grupo-titulo">
                        {g.titulo}
                        {g.inactiva && <span className="pl-insignia pl-insignia-alerta">Etapa inactiva</span>}
                        <span className="pl-ayuda">· {g.requisitos.length}</span>
                    </h2>
                    {g.clave === SIN_ETAPA && sinEtapaActivos > 0 && (
                        <p className="pl-aviso-suave" role="status">
                            {sinEtapaActivos === 1
                                ? '1 requisito activo no tiene etapa: edítalo y elige su etapa antes de publicar.'
                                : `${sinEtapaActivos} requisitos activos no tienen etapa: edítalos y elige la etapa de cada uno antes de publicar.`}
                        </p>
                    )}
                    <ol className="pl-tabla">
                        {g.requisitos.map((r, j) => fila(r, j === 0, j === g.requisitos.length - 1))}
                    </ol>
                </section>
            )) : (
                <ol className="pl-tabla">
                    {requisitos.map((r, indice) => fila(r, indice === 0, indice === requisitos.length - 1))}
                </ol>
            )}
        </div>
    );
};

export default PlantillaRequisitos;
